import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { install } from '../src/install/install.mjs';

function tempHome(t) {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'agent-recall-install-'));
  t.after(() => fs.rmSync(home, { recursive: true, force: true }));
  return home;
}

test('installs once for all agents, keeps foreign files and is idempotent', async t => {
  const home = tempHome(t);
  const primary = path.join(home, '.agents', 'skills', 'agent-recall');
  // An older install that the user added their own helper script to.
  fs.mkdirSync(path.join(primary, 'scripts'), { recursive: true });
  fs.mkdirSync(path.join(primary, 'src', 'sources'), { recursive: true });
  fs.writeFileSync(path.join(primary, '.agent-recall-install.json'), JSON.stringify({ name: 'agent-recall', version: 1 }));
  fs.writeFileSync(path.join(primary, 'src', 'sources', 'old.mjs'), 'old');
  fs.writeFileSync(path.join(primary, 'scripts', 'my-helper.mjs'), 'mine');

  const first = await install({ home, index: false });
  assert.deepEqual(first.actions.map(a => a.action), ['update', 'link']);
  assert.ok(fs.existsSync(path.join(primary, 'SKILL.md')));
  assert.ok(fs.existsSync(path.join(primary, 'src', 'recall.mjs')));
  assert.ok(!fs.existsSync(path.join(primary, 'src', 'sources', 'old.mjs')));
  assert.equal(fs.readFileSync(path.join(primary, 'scripts', 'my-helper.mjs'), 'utf8'), 'mine');
  const claude = path.join(home, '.claude', 'skills', 'agent-recall');
  assert.ok(fs.existsSync(path.join(claude, 'SKILL.md')));

  const second = await install({ home, index: false });
  assert.deepEqual(second.actions.map(a => a.action), ['update', 'linked']);

  const removed = await install({ home, uninstall: true });
  assert.deepEqual(removed.actions.map(a => a.action), ['unlink', 'remove']);
  assert.deepEqual(fs.readdirSync(primary, { recursive: true }).map(p => p.split(path.sep).join('/')).sort(), ['scripts', 'scripts/my-helper.mjs']);
  assert.ok(!fs.existsSync(claude));
});

test('an installed copy runs', async t => {
  const home = tempHome(t);
  const target = path.join(home, 'skill');
  await install({ targets: [target], index: false });
  const { execFileSync } = await import('node:child_process');
  const out = execFileSync(process.execPath, [path.join(target, 'scripts', 'recall.mjs'), '--version'], { encoding: 'utf8' });
  assert.equal(out.trim(), JSON.parse(fs.readFileSync('package.json', 'utf8')).version);
});

test('a Claude skill link pointing somewhere else is never written through', async t => {
  const home = tempHome(t);
  const checkout = path.join(home, 'dev-checkout');
  fs.mkdirSync(checkout);
  fs.writeFileSync(path.join(checkout, 'SKILL.md'), 'dev');
  fs.mkdirSync(path.join(home, '.claude', 'skills'), { recursive: true });
  fs.symlinkSync(checkout, path.join(home, '.claude', 'skills', 'agent-recall'), process.platform === 'win32' ? 'junction' : 'dir');
  const result = await install({ home, index: false });
  assert.deepEqual(result.actions.map(a => a.action), ['install', 'skipped']);
  assert.equal(fs.readFileSync(path.join(checkout, 'SKILL.md'), 'utf8'), 'dev');
  assert.deepEqual(fs.readdirSync(checkout), ['SKILL.md']);
});

#!/usr/bin/env node
// Kept for older instructions; the same as `recall.mjs install`.
const { main } = await import('../src/cli/main.mjs');
await main(['install', ...process.argv.slice(2)]);

import { spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { APP, VERSION } from '../shared/config.mjs';
import { comparablePath } from '../shared/paths.mjs';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const MARKER = '.agent-recall-install.json';
const LEGACY_NAME = 'conversation-recall';
// What an installed skill needs. Everything else in a target folder belongs to the user.
const SHIPPED = ['SKILL.md', 'LICENSE', 'package.json', 'agents', 'references', 'scripts/recall.mjs', 'src'];

function listFiles(relative) {
  const full = path.join(ROOT, relative);
  if (!fs.existsSync(full)) return [];
  if (fs.statSync(full).isFile()) return [relative];
  return fs.readdirSync(full, { recursive: true, withFileTypes: true })
    .filter(entry => entry.isFile())
    .map(entry => path.relative(ROOT, path.join(entry.parentPath, entry.name)));
}

function readMarker(dir) {
  try {
    return JSON.parse(fs.readFileSync(path.join(dir, MARKER), 'utf8'));
  } catch {
    return null;
  }
}

function linkTarget(dir) {
  try {
    return fs.lstatSync(dir).isSymbolicLink() ? fs.realpathSync(dir) : null;
  } catch {
    return null;
  }
}

export function defaultTargets(home = os.homedir()) {
  return {
    primary: path.join(home, '.agents', 'skills', APP.NAME),
    links: [path.join(home, '.claude', 'skills', APP.NAME)],
    legacy: [path.join(home, '.agents', 'skills', LEGACY_NAME), path.join(home, '.claude', 'skills', LEGACY_NAME)],
  };
}

// Copies shipped files into `dir`, removes files a previous install shipped that this one no
// longer does, and leaves every other file alone.
function installCopy(dir, files, actions, dryRun) {
  const previous = readMarker(dir);
  const owned = new Set((previous?.files ?? []).map(file => file.replaceAll('\\', '/')));
  const next = new Set(files.map(file => file.replaceAll('\\', '/')));
  actions.push({ action: previous ? 'update' : 'install', target: dir, files: files.length });
  if (dryRun) return;
  // v1 markers listed no files, but src/ was always entirely the installer's.
  if (previous && !previous.files) fs.rmSync(path.join(dir, 'src'), { recursive: true, force: true });
  for (const file of files) {
    fs.mkdirSync(path.dirname(path.join(dir, file)), { recursive: true });
    fs.copyFileSync(path.join(ROOT, file), path.join(dir, file));
  }
  for (const stale of owned) {
    if (!next.has(stale)) fs.rmSync(path.join(dir, stale), { force: true });
  }
  fs.writeFileSync(path.join(dir, MARKER), `${JSON.stringify({ name: APP.NAME, version: 2, release: VERSION, files: [...next].sort() }, null, 2)}\n`);
}

function removeOwned(dir, actions, dryRun) {
  const marker = readMarker(dir);
  if (!marker) return;
  actions.push({ action: 'remove', target: dir });
  if (dryRun) return;
  for (const file of marker.files ?? []) fs.rmSync(path.join(dir, file), { force: true });
  fs.rmSync(path.join(dir, MARKER), { force: true });
  // v1 markers listed no files; the folder was entirely ours.
  if (!marker.files) fs.rmSync(dir, { recursive: true, force: true });
  else removeEmptyDirs(dir);
}

// Removes the link itself, never what it points to.
function removeLink(link) {
  try {
    fs.unlinkSync(link);
  } catch {
    fs.rmdirSync(link);
  }
}

function removeEmptyDirs(dir) {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) if (entry.isDirectory()) removeEmptyDirs(path.join(dir, entry.name));
  if (!fs.readdirSync(dir).length) fs.rmdirSync(dir);
}

function isLink(dir) {
  try {
    return fs.lstatSync(dir).isSymbolicLink();
  } catch {
    return false;
  }
}

// Same folder after resolving links; a missing folder compares by its path.
function sameDir(a, b) {
  const real = dir => (fs.existsSync(dir) ? fs.realpathSync(dir) : dir);
  return comparablePath(real(a)) === comparablePath(real(b));
}

// A second skill folder (Claude's) becomes a link to the primary copy, so there is one copy
// to update. A link the user pointed elsewhere (a dev checkout) is left alone: nothing is
// ever written through it. Falls back to a copy where links are not allowed.
function installLink(link, primary, files, actions, dryRun) {
  if (isLink(link)) {
    if (sameDir(link, primary)) actions.push({ action: 'linked', target: link, to: primary });
    else actions.push({ action: 'skipped', target: link, reason: `it links to ${linkTarget(link) ?? 'a missing folder'}` });
    return;
  }
  if (fs.existsSync(link)) {
    installCopy(link, files, actions, dryRun);
    return;
  }
  actions.push({ action: 'link', target: link, to: primary });
  if (dryRun) return;
  fs.mkdirSync(path.dirname(link), { recursive: true });
  try {
    fs.symlinkSync(primary, link, process.platform === 'win32' ? 'junction' : 'dir');
  } catch {
    actions.pop();
    installCopy(link, files, actions, dryRun);
  }
}

function startFirstIndex(dir) {
  try {
    spawn(process.execPath, [path.join(dir, 'scripts', 'recall.mjs'), 'sync', '--quiet'], { detached: true, stdio: 'ignore', windowsHide: true }).unref();
  } catch {
    // The first search builds the index instead.
  }
}

/**
 * Installs the skill for every agent on this machine: a copy in ~/.agents/skills (Codex,
 * OpenCode, Cursor and others) and a link from ~/.claude/skills. Idempotent; keeps files it
 * did not write. `targets` replaces the defaults with explicit folders.
 */
export async function install({ targets, dryRun = false, uninstall = false, agentsOnly = false, home, index = true } = {}) {
  const files = SHIPPED.flatMap(listFiles);
  const defaults = defaultTargets(home);
  const explicit = targets?.map(target => path.resolve(target));
  const actions = [];

  if (uninstall) {
    for (const dir of explicit ?? [...defaults.links, defaults.primary, ...defaults.legacy]) {
      if (isLink(dir) && !explicit) {
        actions.push({ action: 'unlink', target: dir });
        if (!dryRun) removeLink(dir);
      } else removeOwned(dir, actions, dryRun);
    }
    return { dryRun, actions };
  }

  for (const dir of explicit ?? [defaults.primary]) {
    if (sameDir(dir, ROOT)) continue;
    installCopy(dir, files, actions, dryRun);
  }
  if (!explicit) {
    if (!agentsOnly) for (const link of defaults.links) installLink(link, defaults.primary, files, actions, dryRun);
    for (const legacy of defaults.legacy) removeOwned(legacy, actions, dryRun);
  }
  if (!dryRun && index) startFirstIndex(explicit?.[0] ?? defaults.primary);
  return { dryRun, actions, version: VERSION };
}

export function renderInstall(result) {
  const lines = result.actions.map(item => `${item.action}: ${item.target}${item.to ? ` -> ${item.to}` : ''}${item.reason ? ` (${item.reason})` : ''}`);
  if (!result.dryRun && result.actions.some(item => ['install', 'update', 'link', 'linked'].includes(item.action))) {
    lines.push('', `Agent Recall ${result.version} is installed. The first index is building in the background.`);
    lines.push('Start a new chat with your agent and ask something like: "what did we decide about X last week?"');
  }
  return lines.join('\n');
}

import { KINDS, LIMITS, RANKING, ROLES } from '../shared/config.mjs';
import { comparablePath, isWithin } from '../shared/paths.mjs';
import { snippet, termHits } from '../shared/text.mjs';
import { PASSAGE_FLAGS } from '../index/passages.mjs';
import { rootResolver, sessionFilter } from '../index/sessions.mjs';

const DAY_MS = 86_400_000;
const passageRank = `bm25(${RANKING.PASSAGE_WEIGHTS.join(', ')})`;
const sessionRank = `bm25(${RANKING.SESSION_WEIGHTS.join(', ')})`;

function idList(ids) {
  return [...ids].map(Number).filter(Number.isInteger).join(',') || '0';
}

function passageCandidates(db, query, filter) {
  return db.prepare(`
    SELECT p.id, p.session_id AS sessionId, p.first_seq AS firstSeq, p.last_seq AS lastSeq, p.ts, p.hash, p.flags, -f.rank AS score
    FROM passages_fts f JOIN passages p ON p.id = f.rowid JOIN sessions s ON s.id = p.session_id
    WHERE passages_fts MATCH ? AND f.rank MATCH '${passageRank}' ${filter.sql}
    ORDER BY f.rank LIMIT ${LIMITS.SEARCH_CANDIDATES}`).all(query.match, ...filter.params);
}

function sessionCandidates(db, query, filter) {
  return db.prepare(`
    SELECT s.id AS sessionId, -f.rank AS score
    FROM sessions_fts f JOIN sessions s ON s.id = f.rowid
    WHERE sessions_fts MATCH ? AND f.rank MATCH '${sessionRank}' ${filter.sql}
    ORDER BY f.rank LIMIT ${LIMITS.SESSION_CANDIDATES}`).all(query.match, ...filter.params);
}

// Which query terms each candidate row contains. Contentless FTS keeps no text, so each
// term is matched separately, restricted to the candidate rows.
function termCoverage(db, table, ids, terms) {
  const covered = new Map();
  if (!ids.size) return covered;
  const list = idList(ids);
  terms.forEach((term, index) => {
    for (const row of db.prepare(`SELECT rowid FROM ${table} WHERE ${table} MATCH ? AND rowid IN (${list})`).all(term.fts)) {
      if (!covered.has(row.rowid)) covered.set(row.rowid, new Set());
      covered.get(row.rowid).add(index);
    }
  });
  return covered;
}

function passageWeight(passage) {
  let score = passage.score;
  if (passage.flags & PASSAGE_FLAGS.RECALL) score *= RANKING.RECALL_PENALTY;
  if (passage.flags & PASSAGE_FLAGS.SUMMARY) score *= RANKING.SUMMARY_PENALTY;
  return score;
}

function recencyFactor(updatedAt, now) {
  const time = Date.parse(updatedAt ?? '');
  if (!Number.isFinite(time)) return 1;
  const ageDays = Math.max(0, (now - time) / DAY_MS);
  return 1 + RANKING.RECENCY_BOOST * 0.5 ** (ageDays / RANKING.RECENCY_HALF_LIFE_DAYS);
}

function inProject(session, cwd) {
  if (!cwd || !session.cwd) return false;
  if (isWithin(session.cwd, cwd) || isWithin(cwd, session.cwd)) return true;
  // Worktrees and clones of the same project share its folder name.
  const name = path => comparablePath(path).split('/').at(-1);
  return name(session.cwd) === name(cwd);
}

// Picks the message in a passage that best shows why it matched.
function bestMessage(db, passage, stems) {
  const rows = db.prepare(`SELECT seq, ts, role, kind, text FROM messages WHERE session_id = ? AND seq BETWEEN ? AND ? ORDER BY seq`)
    .all(passage.sessionId, passage.firstSeq, passage.lastSeq);
  let best = null;
  for (const row of rows) {
    const { hits, matched } = termHits(row.text, stems);
    const value = matched.size * 10 + Math.min(hits.length, 9) + (row.role === ROLES.USER && row.kind === KINDS.TEXT ? 0.5 : 0);
    if (!best || value > best.value) best = { value, row };
  }
  return best?.row ?? rows[0] ?? null;
}

/**
 * Ranks root conversations for a parsed query. Passages score by bm25; a conversation scores
 * by its best passages (from itself and its subagents), its title, how many query terms it
 * covers anywhere, the current project and recency. Copies of the same turn (forks, resumed
 * sessions) count once, for the oldest session that holds them.
 */
export function rankConversations(db, query, options = {}) {
  const limit = Math.min(Math.max(1, options.limit ?? LIMITS.SEARCH_DEFAULT), LIMITS.SEARCH_MAX);
  if (!query.terms.length) return { hits: [], considered: 0 };
  // Archiving applies to a whole conversation, so it is checked on the root below.
  const filter = sessionFilter({ ...options, archived: 'include' });
  const now = options.now ?? Date.now();
  const resolve = rootResolver(db);

  const passages = passageCandidates(db, query, filter);
  const titled = sessionCandidates(db, query, filter);
  for (const row of [...passages, ...titled]) resolve.load(row.sessionId);

  // Keep one copy of each duplicated passage: the one in the oldest session.
  const byHash = new Map();
  // Age of a session for picking the original: started earlier, then finished earlier (a
  // fork that continued is newer than what it copied).
  const age = sessionId => {
    const session = resolve.session(sessionId);
    return `${session?.created_at ?? ''}|${session?.updated_at ?? ''}`;
  };
  for (const passage of passages) {
    const current = byHash.get(passage.hash);
    if (!current || age(passage.sessionId) < age(current.sessionId)) byHash.set(passage.hash, passage);
  }
  const unique = [...byHash.values()];
  const passageTerms = termCoverage(db, 'passages_fts', new Set(unique.map(p => p.id)), query.terms);
  const sessionTerms = termCoverage(db, 'sessions_fts', new Set(titled.map(s => s.sessionId)), query.terms);

  const groups = new Map();
  const groupFor = sessionId => {
    const root = resolve.root(sessionId);
    if (!root || options.exclude?.has(root.native_id)) return null;
    if (options.archived === 'exclude' && root.archived) return null;
    if (options.archived === 'only' && !root.archived) return null;
    if (!groups.has(root.id)) groups.set(root.id, { root, passages: [], title: 0, terms: new Set() });
    return groups.get(root.id);
  };
  for (const passage of unique) {
    const group = groupFor(passage.sessionId);
    if (!group) continue;
    group.passages.push({ ...passage, weight: passageWeight(passage) });
    for (const term of passageTerms.get(passage.id) ?? []) group.terms.add(term);
  }
  for (const row of titled) {
    const group = groupFor(row.sessionId);
    if (!group) continue;
    // Only the conversation's own name counts; subagent descriptions are the agent's words.
    if (row.sessionId !== group.root.id) continue;
    group.title = row.score;
    for (const term of sessionTerms.get(row.sessionId) ?? []) group.terms.add(term);
  }

  // A chat that opened by asking for a conversation is titled after what it looked for.
  const openingFlags = db.prepare('SELECT flags FROM passages WHERE session_id = ? AND first_seq = 0');
  const scored = [...groups.values()].map(group => {
    if (group.title && (openingFlags.get(group.root.id)?.flags ?? 0) & PASSAGE_FLAGS.RECALL) group.title *= RANKING.RECALL_PENALTY;
    group.passages.sort((a, b) => b.weight - a.weight);
    const [first = 0, ...rest] = group.passages.map(p => p.weight);
    const extra = RANKING.EXTRA_PASSAGE_WEIGHTS.reduce((sum, weight, i) => sum + weight * (rest[i] ?? 0), 0);
    const coverage = group.terms.size / query.terms.length;
    let score = (RANKING.BASE_SCORE + first + extra + RANKING.TITLE_WEIGHT * group.title) * (1 + RANKING.COVERAGE_WEIGHT * coverage ** 2);
    if (inProject(group.root, options.cwd)) score *= RANKING.CURRENT_PROJECT_BOOST;
    score *= recencyFactor(group.root.updated_at, now);
    return { ...group, coverage, score };
  }).sort((a, b) => b.score - a.score);

  const hits = scored.slice(0, limit).map(group => ({
    root: group.root,
    score: group.score,
    coverage: group.coverage,
    matched: query.terms.filter((_, i) => group.terms.has(i)).map(term => term.text),
    missing: query.terms.filter((_, i) => !group.terms.has(i)).map(term => term.text),
    titleMatched: group.title > 0,
    matches: group.passages.slice(0, LIMITS.MATCHES_PER_HIT).map(passage => {
      const message = bestMessage(db, passage, query.stems);
      const session = resolve.session(passage.sessionId);
      return {
        session,
        seq: message?.seq ?? passage.firstSeq,
        firstSeq: passage.firstSeq,
        lastSeq: passage.lastSeq,
        role: message?.role ?? null,
        kind: message?.kind ?? null,
        at: message?.ts ?? passage.ts,
        snippet: message ? snippet(message.text, query.stems) : '',
      };
    }),
  }));
  return { hits, considered: scored.length };
}

import { LIMITS } from '../shared/config.mjs';
import { stem, words } from '../shared/text.mjs';

// Words that carry no topic. The second line is how people ask for recall ("find the chat
// where we discussed..."); matching them ranks recall requests above the conversation sought.
const STOPWORDS = new Set(`
a about above after again all also am an and any are as at be because been before being below between both but by
can could did do does doing down during each few for from further had has have having he her here hers him his how
i if in into is it its itself just me more most my no nor not now of off on once only or other our ours out over own
same she should so some such than that the their theirs them then there these they this those through to too under
until up very was we were what when where which while who whom why will with would you your yours yourself let lets
conversation conversations chat chats session sessions thread threads transcript transcripts talked talk discussed
discuss discussion mentioned mention remember recall earlier previous previously past ago find search look looking
`.split(/\s+/).filter(Boolean));

// Tokens that the FTS tokenizer would split (paths, file names, flags, kebab and snake case)
// are searched as a phrase so "codex-lb" does not match every "codex" and every "lb".
const CODE_TOKEN = /[\p{L}\p{N}]+(?:[._\-/\\:@#][\p{L}\p{N}]+)+/gu;

const quote = value => `"${value.replaceAll('"', '""')}"`;

function termFor(tokens, phrase) {
  const text = tokens.join(' ');
  return {
    text,
    phrase,
    tokens,
    stems: tokens.map(stem),
    // A phrase also matches when its parts appear apart, just with a lower score.
    fts: phrase && tokens.length > 1 ? `(${quote(text)} OR (${tokens.map(quote).join(' AND ')}))` : quote(text),
  };
}

/**
 * Turns free text into search terms. Quoted text and code-like tokens become phrases;
 * everything else becomes single words minus stopwords. When every word is a stopword the
 * words are kept, so a query is never silently empty.
 */
export function parseQuery(raw) {
  let text = String(raw ?? '').slice(0, LIMITS.QUERY_MAX_CHARS).replace(/[‘’“”]/g, match => (match === '‘' || match === '’' ? "'" : '"'));
  const terms = [];
  const seen = new Set();
  const add = term => {
    if (!term.tokens.length || seen.has(term.text) || terms.length >= LIMITS.QUERY_MAX_TERMS) return;
    seen.add(term.text);
    terms.push(term);
  };

  text = text.replace(/"([^"]+)"/g, (_, inner) => {
    add(termFor(words(inner), true));
    return ' ';
  });
  text = text.replace(CODE_TOKEN, match => {
    add(termFor(words(match), true));
    return ' ';
  });
  const plain = words(text);
  const topical = plain.filter(word => !STOPWORDS.has(word));
  for (const word of (topical.length || terms.length ? topical : plain)) add(termFor([word], false));

  return {
    raw: String(raw ?? ''),
    terms,
    match: terms.map(term => term.fts).join(' OR '),
    stems: new Set(terms.flatMap(term => term.stems)),
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { COMMAND_ALIASES, COMMANDS, parseArgs } from '../src/cli/args.mjs';

const root = path.resolve(import.meta.dirname, '..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');
const skill = read('SKILL.md');

function frontmatter(text) {
  const block = text.match(/^---\n([\s\S]*?)\n---\n/)?.[1] ?? '';
  return Object.fromEntries(block.split('\n').map(line => line.match(/^([a-z-]+):\s*(.*)$/)).filter(Boolean).map(m => [m[1], m[2]]));
}

test('SKILL.md is the only skill and its frontmatter is valid', () => {
  const meta = frontmatter(skill);
  assert.equal(meta.name, 'agent-recall');
  assert.ok(meta.description.length > 50 && meta.description.length <= 1024);
  const others = fs.globSync('**/SKILL.md', { cwd: root, exclude: name => name === 'node_modules' || name === '.git' });
  assert.deepEqual(others, ['SKILL.md']);
});

test('every file SKILL.md links to exists', () => {
  for (const [, target] of skill.matchAll(/\]\(([^)#]+)\)/g)) assert.ok(fs.existsSync(path.join(root, target)), target);
});

test('every command SKILL.md shows parses against the CLI', () => {
  const lines = [...skill.matchAll(/recall\.mjs"?\s+([^\n`]+)/g)].map(match => match[1].trim());
  assert.ok(lines.length >= 4);
  for (const line of lines) {
    const [name, ...args] = line.replace(/<[^>]+>/g, 'x').split(/\s+/).filter(Boolean);
    if (name === '<command>' || name === 'x') continue;
    const command = COMMAND_ALIASES[name] ?? name;
    assert.ok(COMMANDS[command], `unknown command in SKILL.md: ${line}`);
    assert.doesNotThrow(() => parseArgs(command, args), line);
  }
  for (const [, inline] of skill.matchAll(/`((?:search|read|recent|show|attachment|doctor|sync)\b[^`]*)`/g)) {
