  }
  home.jsonl(project('-work-long', 'long-1'), records);
  const seen = [];
  let from = 0;
  for (let pages = 0; from !== null && pages < 50; pages += 1) {
    const page = await recall.read('long-1', { from, maxChars: 8000 });
    seen.push(...page.messages.map(m => m.seq));
