  const tail = await recall.read('long-1', { last: 2 });
  assert.deepEqual(tail.messages.map(m => m.seq), [118, 119]);
  const grep = await recall.read('long-1', { grep: 'question 42', context: 0 });
  assert.deepEqual(grep.grepHits, [84]);
});

